// CloudWatch Synthetics canary for user-journey-level black-box monitoring (ADR-0030).
//
// 検証対象は次の4ステップに限定する(認証機能は本アプリに存在しないため対象外、書き込み系APIも対象外):
//   1. frontend-delivery   : CloudFront経由のフロントエンド配信確認
//   2. api-health-check    : CloudFront経由のAPIヘルスチェック(GET /health)
//   3. graphql-read-query  : CloudFront経由のGraphQL読み取りクエリ(capitalCities。固定データでDBを通らない)
//   4. graphql-routes-query: CloudFront経由のGraphQL読み取りクエリ(routes。GraphQL -> TypeORM -> PostgreSQL を通る)
//
// step 4 は deploy.yml の deploy 後の確認にも使う(Issue #674、ADR-0035)。CloudFront は geo restriction で
// JP からのアクセスのみ許可しており、GitHub-hosted runner からは確認できないため、東京リージョンで動く
// この canary の結果を deploy.yml が待つ。定期実行のたびに行が増えるため、書き込みクエリは入れない。
//
// 全ステップはCloudFront経由でアクセスする(PR #478)。ALB直接アクセス防止(origin-verifyヘッダー)は
// CloudFront自身のcustom_header(terraform/modules/cloudfront)がサーバー側で付与する統制であり、
// canaryはヘッダーの取得・付与に関与しない(ADR-0030「更新」節参照)。

const synthetics = require('@aws/synthetics-puppeteer');

const buildJsonPostOptions = (urlString, body) => {
  const url = new URL(urlString);
  return {
    hostname: url.hostname,
    method: 'POST',
    path: `${url.pathname}${url.search || ''}`,
    port: url.protocol === 'https:' ? 443 : 80,
    protocol: url.protocol,
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  };
};

const consumeAndCheckStatus = (stepName) => async (res) => {
  return new Promise((resolve, reject) => {
    if (res.statusCode < 200 || res.statusCode > 299) {
      reject(
        new Error(
          `${stepName} failed with status ${res.statusCode} ${res.statusMessage}`,
        ),
      );
      return;
    }
    res.on('data', () => {});
    res.on('end', resolve);
    res.on('error', reject);
  });
};

const jsonCallback =
  (stepName, validateData = () => undefined) =>
  async (res) => {
    return new Promise((resolve, reject) => {
      if (res.statusCode < 200 || res.statusCode > 299) {
        reject(
          new Error(
            `${stepName} failed with status ${res.statusCode} ${res.statusMessage}`,
          ),
        );
        return;
      }
      let responseBody = '';
      res.on('data', (chunk) => {
        responseBody += chunk;
      });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(responseBody);
          if (parsed.errors && parsed.errors.length > 0) {
            reject(
              new Error(
                `${stepName} returned GraphQL errors: ${JSON.stringify(parsed.errors)}`,
              ),
            );
            return;
          }
          const validationError = validateData(parsed.data);
          if (validationError) {
            reject(new Error(`${stepName} ${validationError}`));
            return;
          }
          resolve();
        } catch (err) {
          reject(
            new Error(`${stepName} returned invalid JSON: ${err.message}`),
          );
        }
      });
      res.on('error', reject);
    });
  };

const userJourneyCanary = async function () {
  const frontendUrl = process.env.FRONTEND_URL;
  const apiHealthUrl = process.env.API_HEALTH_URL;
  const apiGraphqlUrl = process.env.API_GRAPHQL_URL;
  const graphqlQuery = process.env.GRAPHQL_QUERY;
  const graphqlRoutesQuery = process.env.GRAPHQL_ROUTES_QUERY;

  // Step 1: frontend delivery via CloudFront
  await synthetics.executeHttpStep(
    'frontend-delivery',
    frontendUrl,
    consumeAndCheckStatus('frontend-delivery'),
  );

  // Step 2: API health check via CloudFront
  await synthetics.executeHttpStep(
    'api-health-check',
    apiHealthUrl,
    consumeAndCheckStatus('api-health-check'),
  );

  // Step 3: GraphQL read-only query via CloudFront
  await synthetics.executeHttpStep(
    'graphql-read-query',
    buildJsonPostOptions(apiGraphqlUrl, { query: graphqlQuery }),
    jsonCallback('graphql-read-query'),
  );

  // Step 4: GraphQL read-only query that goes through the database via CloudFront
  await synthetics.executeHttpStep(
    'graphql-routes-query',
    buildJsonPostOptions(apiGraphqlUrl, { query: graphqlRoutesQuery }),
    jsonCallback('graphql-routes-query', (data) =>
      data && Array.isArray(data.routes)
        ? undefined
        : `returned unexpected data: ${JSON.stringify(data)}`,
    ),
  );
};

exports.handler = async () => {
  return await userJourneyCanary();
};
